from datetime import datetime,timezone
import os,json,subprocess
from pathlib import Path
p=Path('/usr/lib/wsl/lib/nvidia-smi')
r={'read_at_utc':datetime.now(timezone.utc).isoformat(),'loadavg':os.getloadavg(),'logical_cpus':os.cpu_count(),'GPU_snapshot':{},'GPU_process_headers':[]}
for name,query in [('gpu','--query-gpu=index,utilization.gpu,utilization.memory,memory.used,memory.total,pstate,clocks.sm,power.draw'),('apps','--query-compute-apps=pid,used_memory')]:
    x=subprocess.run([str(p),query,'--format=csv'],capture_output=True,text=True,timeout=15)
    r['GPU_snapshot'][name]={'exit':x.returncode,'stdout':x.stdout,'stderr':x.stderr}
if r['GPU_snapshot']['apps']['exit']==0:
    for line in r['GPU_snapshot']['apps']['stdout'].splitlines()[1:]:
        pid=int(line.split(',',1)[0].strip())
        proc=Path('/proc')/str(pid)
        if not proc.exists():
            r['GPU_process_headers'].append({'pid':pid,'status':'ended_between_GPU_and_proc_read'})
            continue
        parts=[s.decode() for s in (proc/'cmdline').read_bytes().split(b'\0') if s]
        fields={x.split(':',1)[0]:x.split(':',1)[1].strip() for x in (proc/'status').read_text().splitlines() if x.split(':',1)[0] in {'Name','State','VmRSS','Threads','PPid'}}
        r['GPU_process_headers'].append({'pid':pid,'status':fields,'entry_scripts':[s for s in parts if s.endswith('.py')]})
print(json.dumps(r))
